const TZ = 'Africa/Addis_Ababa';
let events = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) { events = events.concat(j); }
  else if (j && j.title) { events.push(j); }
}
const dayKey = (d) => d.toLocaleDateString('en-CA', { timeZone: TZ });
const fmtTime = (d) => d.toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false });
const today = dayKey(new Date());
const todays = events
  .filter((e) => e.impact === 'High' && e.date && dayKey(new Date(e.date)) === today)
  .sort((a, b) => new Date(a.date) - new Date(b.date));
const lines = todays.map((e) => fmtTime(new Date(e.date)) + ' | ' + e.country + ' | ' + e.title + ' | forecast: ' + (e.forecast || 'n/a') + ' | previous: ' + (e.previous || 'n/a'));
return [{ json: { count: todays.length, eventsText: lines.length ? lines.join('\n') : 'No high-impact events today.' } }];

const news = $input.all().map((i) => i.json).filter((j) => j && j.title).slice(0, 8);
const headlines = news.length ? news.map((n, i) => (i + 1) + '. ' + n.title).join('
') : 'No headlines available.';
const ev = $('Today High-Impact Events').first().json;
const context = 'Today: ' + new Date().toISOString().slice(0, 10) + '

HIGH-IMPACT EVENTS TODAY (times in Addis Ababa time, UTC+3):
' + ev.eventsText + '

LATEST FOREX HEADLINES:
' + headlines;
return [{ json: { context } }];

const TZ = 'Africa/Addis_Ababa';
let events = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) { events = events.concat(j); }
  else if (j && j.title) { events.push(j); }
}
const fmtTime = (d) => d.toLocaleTimeString('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hour12: false });
const now = Date.now();
const upcoming = events
  .filter((e) => {
    if (e.impact !== 'High' || !e.date) return false;
    const mins = (new Date(e.date).getTime() - now) / 60000;
    return mins > 15 && mins <= 45;
  })
  .sort((a, b) => new Date(a.date) - new Date(b.date));
if (upcoming.length === 0) return [];
const lines = upcoming.map((e) => fmtTime(new Date(e.date)) + ' | ' + e.country + ' | ' + e.title + ' | forecast: ' + (e.forecast || 'n/a') + ' | previous: ' + (e.previous || 'n/a'));
return [{ json: { count: upcoming.length, eventsText: lines.join('\n') } }];
